problem:
Problem description
- There is a set $$\mathcal{I}$$ of non-preemptive activities, indexed by $$i \in \mathcal{I}$$, each with a fixed duration $$d_i$$ measured in days.
- The activities form a precedence network described by a set of immediate precedence pairs $$\mathcal{P} \subseteq \mathcal{I} \times \mathcal{I}$$, where each pair means that the predecessor must finish before the successor can begin.
- The schedule is planned over a time horizon $$T$$ measured in days.
- A uniform work cost is incurred at rate $$c_{\mathrm{work}}$$ per day for the project timeline.
- A special machine must be rented continuously over a designated interval determined by two anchor activities, one that marks the rental start and one that marks the rental end.
- The machine rental cost is incurred at rate $$c_{\mathrm{mach}}$$ per day over that rental interval.
- The planning goal is to choose feasible activity start times so that all precedence requirements are respected and the total cost from work time and machine rental time is minimized.
- A solution is represented by:
  - $$s_i$$, the start time of activity $$i \in \mathcal{I}$$,
  - $$f_i$$, the finish time of activity $$i \in \mathcal{I}$$,
  - $$C_{\max}$$, the project completion time,
  - $$r_{\mathrm{mach}}$$, the total rental duration of the special machine,
  - $$Z$$, the total project cost.

Input Format
{
  "activities": {
    "type": "array",
    "description": "List of activities in $$\\mathcal{I}$$, indexed by $$i$$.",
    "items": {
      "id": "activity identifier",
      "duration": "processing time $$d_i$$ in days"
    }
  },
  "precedence_arcs": {
    "type": "array",
    "description": "List of ordered pairs in $$\\mathcal{P}$$, where each pair indicates that the first activity must finish before the second activity starts.",
    "items": {
      "predecessor": "activity index $$i$$",
      "successor": "activity index $$j$$"
    }
  },
  "work_cost_per_day": {
    "type": "number",
    "description": "Daily work cost $$c_{\\mathrm{work}}$$."
  },
  "machine_rental_cost_per_day": {
    "type": "number",
    "description": "Daily rental cost $$c_{\\mathrm{mach}}$$ for the special machine."
  },
  "machine_start_activity": {
    "type": "activity",
    "description": "Anchor activity $$i^{\\mathrm{s}}$$ whose start time defines the beginning of the machine rental interval."
  },
  "machine_end_activity": {
    "type": "activity",
    "description": "Anchor activity $$i^{\\mathrm{e}}$$ whose finish time defines the end of the machine rental interval."
  },
  "time_horizon": {
    "type": "number",
    "description": "Planning horizon $$T$$ in days, if an upper bound on completion time is needed."
  },
  "time_unit": {
    "type": "string",
    "description": "Time is measured in days."
  }
}

Output Format
{
  "start_times": {
    "type": "object",
    "description": "Planned start time $$s_i$$ for each activity $$i \\in \\mathcal{I}$$."
  },
  "finish_times": {
    "type": "object",
    "description": "Planned finish time $$f_i$$ for each activity $$i \\in \\mathcal{I}$$."
  },
  "project_completion_time": {
    "type": "number",
    "description": "Project completion time $$C_{\\max}$$."
  },
  "machine_rental_duration": {
    "type": "number",
    "description": "Total machine rental duration $$r_{\\mathrm{mach}}$$."
  },
  "total_cost": {
    "type": "number",
    "description": "Minimum total cost $$Z$$."
  }
}

